<header>
  <h1>My Bookmarks</h1>
  <p>Save a link, and it lands under its topic.</p>
</header>

<div class="wrap">
  <div class="add-card">
    <div class="add-row">
      <div class="field">
        <label for="url">Link address</label>
        <input id="url" type="text" placeholder="https://…" />
      </div>
      <div class="field">
        <label for="title">Title</label>
        <input id="title" type="text" placeholder="What is this link?" />
      </div>
      <div class="field">
        <label for="topic">Topic</label>
        <input id="topic" type="text" placeholder="e.g. Design, Recipes" />
      </div>
      <button class="primary" id="save">Save link</button>
    </div>
  </div>

  <div id="list"></div>
</div>

<script>
  const seed = [
    { url: "https://www.smashingmagazine.com/", title: "Smashing Magazine", topic: "Design" },
    { url: "https://refactoring.guru/", title: "Refactoring Guru", topic: "Development" },
    { url: "https://www.bbcgoodfood.com/", title: "BBC Good Food", topic: "Recipes" },
  ];
  let bookmarks = JSON.parse(localStorage.getItem("bm") || "null") || seed.slice();

  function persist() { localStorage.setItem("bm", JSON.stringify(bookmarks)); }

  function render(flashId) {
    const list = document.getElementById("list");
    list.innerHTML = "";
    if (bookmarks.length === 0) {
      list.innerHTML = '<div class="empty">No links saved yet.<br>Add your first one above.</div>';
      return;
    }
    const topics = {};
    bookmarks.forEach((b, i) => { (topics[b.topic || "Untitled topic"] ||= []).push({ ...b, i }); });
    Object.keys(topics).sort((a, b) => a.localeCompare(b)).forEach(topic => {
      const group = document.createElement("div");
      group.className = "topic-group";
      group.innerHTML = `<h2 class="topic-head">${escapeHtml(topic)} <span class="topic-count">${topics[topic].length}</span></h2>`;
      topics[topic].forEach(b => {
        const el = document.createElement("div");
        el.className = "bm" + (b.i === flashId ? " flash" : "");
        el.innerHTML = `<a href="${escapeAttr(b.url)}" target="_blank" rel="noopener">${escapeHtml(b.title || b.url)}</a>
                        <div class="url">${escapeHtml(b.url)}</div>`;
        group.appendChild(el);
      });
      list.appendChild(group);
    });
  }

  function escapeHtml(s) { return (s || "").replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c])); }
  function escapeAttr(s) { return escapeHtml(s).replace(/"/g, "&quot;"); }

  document.getElementById("save").addEventListener("click", () => {
    const url = document.getElementById("url").value.trim();
    const title = document.getElementById("title").value.trim();
    const topic = document.getElementById("topic").value.trim();
    if (!url) { document.getElementById("url").focus(); return; }
    bookmarks.push({ url, title, topic });
    persist();
    document.getElementById("url").value = "";
    document.getElementById("title").value = "";
    document.getElementById("topic").value = "";
    document.getElementById("url").focus();
    render(bookmarks.length - 1);
  });

  render();
  document.body.setAttribute("data-harness-ready", "true");
</script>
